import express, { Express, NextFunction, Request, Response } from "express";
import { ProjectService, TaskService, UserService } from "../application";
import {
  ConflictError,
  isTaskStatus,
  NotFoundError,
  TASK_STATUSES,
  TaskFilter,
  TaskStatus,
  ValidationError,
} from "../domain";

export interface Services {
  users: UserService;
  projects: ProjectService;
  tasks: TaskService;
}

type Body = Record<string, unknown>;

function bodyOf(req: Request): Body {
  const body: unknown = req.body;
  if (typeof body !== "object" || body === null || Array.isArray(body)) {
    throw new ValidationError("Request body must be a JSON object");
  }
  return body as Body;
}

function requiredString(body: Body, field: string): string {
  const value = body[field];
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new ValidationError(`"${field}" must be a non-empty string`);
  }
  return value;
}

function optionalString(body: Body, field: string, fallback: string): string {
  const value = body[field];
  if (value === undefined || value === null) {
    return fallback;
  }
  if (typeof value !== "string") {
    throw new ValidationError(`"${field}" must be a string`);
  }
  return value;
}

function optionalDate(body: Body, field: string): Date | undefined {
  const value = body[field];
  if (value === undefined || value === null) {
    return undefined;
  }
  if (typeof value !== "string") {
    throw new ValidationError(`"${field}" must be an ISO 8601 date string`);
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new ValidationError(`"${field}" must be a valid ISO 8601 date`);
  }
  return date;
}

function parseStatus(value: unknown, field: string): TaskStatus | undefined {
  if (value === undefined) {
    return undefined;
  }
  if (!isTaskStatus(value)) {
    throw new ValidationError(`"${field}" must be one of: ${TASK_STATUSES.join(", ")}`);
  }
  return value;
}

function queryString(req: Request, field: string): string | undefined {
  const value: unknown = req.query[field];
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== "string") {
    throw new ValidationError(`Query parameter "${field}" must be a single string`);
  }
  return value;
}

function param(req: Request, name: string): string {
  const value: unknown = req.params[name];
  if (typeof value !== "string") {
    throw new ValidationError(`Missing path parameter "${name}"`);
  }
  return value;
}

export function createApp(services: Services): Express {
  const app = express();
  app.use(express.json());

  app.get("/health", (_req, res) => {
    res.json({ status: "ok" });
  });

  app.post("/users", (req, res) => {
    const body = bodyOf(req);
    res.status(201).json(services.users.register(requiredString(body, "name")));
  });

  app.get("/users", (_req, res) => {
    res.json(services.users.list());
  });

  app.get("/users/:userId", (req, res) => {
    res.json(services.users.get(param(req, "userId")));
  });

  app.post("/projects", (req, res) => {
    const body = bodyOf(req);
    res.status(201).json(services.projects.create(requiredString(body, "name")));
  });

  app.get("/projects", (_req, res) => {
    res.json(services.projects.list());
  });

  app.get("/projects/:projectId", (req, res) => {
    res.json(services.projects.get(param(req, "projectId")));
  });

  app.post("/projects/:projectId/tasks", (req, res) => {
    const body = bodyOf(req);
    const task = services.tasks.create({
      projectId: param(req, "projectId"),
      title: requiredString(body, "title"),
      description: optionalString(body, "description", ""),
      dueDate: optionalDate(body, "dueDate"),
      status: parseStatus(body["status"], "status"),
    });
    res.status(201).json(task);
  });

  app.get("/projects/:projectId/tasks", (req, res) => {
    const filter: TaskFilter = {
      status: parseStatus(queryString(req, "status"), "status"),
      assigneeId: queryString(req, "assigneeId"),
    };
    res.json(services.tasks.list(param(req, "projectId"), filter));
  });

  app.get("/projects/:projectId/tasks/:taskId", (req, res) => {
    res.json(services.tasks.get(param(req, "projectId"), param(req, "taskId")));
  });

  app.put("/projects/:projectId/tasks/:taskId/assignee", (req, res) => {
    const body = bodyOf(req);
    const task = services.tasks.assign(
      param(req, "projectId"),
      param(req, "taskId"),
      requiredString(body, "userId"),
    );
    res.json(task);
  });

  app.post("/projects/:projectId/tasks/:taskId/done", (req, res) => {
    res.json(services.tasks.markDone(param(req, "projectId"), param(req, "taskId")));
  });

  app.use((_req, res) => {
    res.status(404).json({ error: "Route not found" });
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (err instanceof ValidationError) {
      res.status(400).json({ error: err.message });
    } else if (err instanceof NotFoundError) {
      res.status(404).json({ error: err.message });
    } else if (err instanceof ConflictError) {
      res.status(409).json({ error: err.message });
    } else if (err instanceof SyntaxError) {
      res.status(400).json({ error: "Malformed JSON body" });
    } else {
      console.error(err);
      res.status(500).json({ error: "Internal server error" });
    }
  });

  return app;
}

