import { ProjectService, TaskService, UserService } from "../application";
import { createApp } from "./http-app";
import {
  InMemoryProjectRepository,
  InMemoryTaskRepository,
  InMemoryUserRepository,
} from "./in-memory-repositories";
import { SystemClock, UuidGenerator } from "./system-adapters";

const ids = new UuidGenerator();
const clock = new SystemClock();
const userRepository = new InMemoryUserRepository();
const projectRepository = new InMemoryProjectRepository();
const taskRepository = new InMemoryTaskRepository();

const app = createApp({
  users: new UserService(userRepository, ids),
  projects: new ProjectService(projectRepository, ids, clock),
  tasks: new TaskService(taskRepository, projectRepository, userRepository, ids, clock),
});

const port = Number(process.env.PORT ?? 3000);

app.listen(port, () => {
  console.log(`Task management API listening on http://localhost:${port}`);
});

